 /// Indice del prossimo descrittore di periferica CE disponibile
 natl next_ce;

-// ( SOLUZIONE 2025-09-10
-//   SOLUZIONE 2025-09-10 )
+extern "C" natl c_ceasyncread_n(natl id, char *buf, natl quanti)
+{
+	if (id >= next_ce) {
+		flog(LOG_WARN, "ceasyncread_n: ce non riconosciuto: %u", id);
+		abort_p();
+	}
+
+	if (!quanti) {
+		flog(LOG_WARN, "ceasyncread_n: quanti == 0");
+		abort_p();
+	}
+
+	if (!access(buf, quanti, true)) {
+		flog(LOG_WARN, "ceasyncread_n: buffer non accessibile: %p, %d", buf, quanti);
+		abort_p();
+	}
+
+	des_ce *ce = &array_ce[id];
+	sem_wait(ce->mutex);
+
+	if (ce->cur == 0xFFFFFFFF && ce->last == 0xFFFFFFFF) {
+		for (int i = 0; i < MAX_CE_ASYNC; i++) {
+			if (!ce->tr[i].buf) {
+				ce->tr[i].buf = buf;
+				ce->tr[i].quanti = quanti;
+				ce->tr[i].next = 0xFFFFFFFF;
+				ce->last = i;
+				sem_signal(ce->sync);
+				sem_signal(ce->mutex);
+				return i;
+			}
+		}
+		sem_signal(ce->mutex);
+		return 0xFFFFFFFF;
+	}
+
+	if (ce->last == 0xFFFFFFFF) {
+		sem_signal(ce->mutex);
+		return 0xFFFFFFFF;
+	}
+
+	natl next_trid = ce->tr[ce->last].next;
+	if (next_trid == 0xFFFFFFFF) {
+		sem_signal(ce->mutex);
+		return 0xFFFFFFFF;
+	}
+
+	if (!ce->tr[next_trid].buf) {
+		ce->tr[next_trid].buf = buf;
+		ce->tr[next_trid].quanti = quanti;
+		ce->tr[next_trid].next = 0xFFFFFFFF;
+		ce->tr[ce->last].next = next_trid;
+		ce->last = next_trid;
+	}
+
+	sem_signal(ce->mutex);
+	return next_trid;
+}

 extern "C" void c_cewait(natl id, natl trid)
 {
@@ -704,8 +760,43 @@ extern "C" void c_cewait(natl id, natl trid)
 /// Corpo del processo esterno delle periferiche CE
 extern "C" void estern_ce(natq id)
 {
-// ( SOLUZIONE 2025-09-10
-//   SOLUZIONE 2025-09-10 )
+	des_ce *ce = &array_ce[id];
+
+	for (;;) {
+		sem_wait(ce->sync);
+
+		if (ce->cur == 0xFFFFFFFF) {
+			ce->waiting--;
+			continue;
+		}
+
+		natl active = ce->cur;
+		if (ce->tr[active].next != 0) {
+			ioaddr rbr = ce->iRBR;
+			char byte = *(char*)rbr;
+
+			*(ce->tr[active].buf) = byte;
+			ce->tr[active].buf++;
+			ce->tr[active].quanti--;
+
+			if (ce->tr[active].quanti == 0) {
+				ce->tr[active].next = 0;
+				sem_signal(ce->sync);
+				ce->cur = 0xFFFFFFFF;
+				if (ce->last != 0xFFFFFFFF) {
+					ce->cur = ce->last;
+					sem_signal(ce->sync);
+				}
+			} else {
+				sem_signal(ce->sync);
+			}
+		} else if (ce->last != 0xFFFFFFFF) {
+			ce->cur = ce->last;
+			sem_signal(ce->sync);
+		} else {
+			ce->waiting--;
+		}
+	}
 }

